//! Runtime support for parsers generated by [prpr](https://github.com/tanakh/prpr).
//!
//! Generated parsers depend on this crate unless the runtime is inlined into them.

#![no_std]

extern crate alloc;
#[cfg(feature = "proc-macro2")]
extern crate std;

mod rt;
pub use rt::*;

#[cfg(feature = "proc-macro2")]
mod source_text;
#[cfg(feature = "proc-macro2")]
pub use source_text::SourceText;

/// The source code of the runtime, for inlining it into generated files.
#[doc(hidden)]
pub const SOURCE: &str = include_str!("rt.rs");
